mapper.select:
SELECT * FROM (
  SELECT ROWNUM AS RNUM, A.* FROM (
    SELECT 
         , C.CD_NM AS PNT_TYPE_NM
         , SUM(L.PNT_AMT) OVER (ORDER BY L.LEDGER_NO) AS CUM_AMT
      FROM TB_PNT_LEDGER L
      LEFT JOIN TB_CMM_CODE C ON C.GRP_CD = 'PNT_TYPE' AND C.CD = L.PNT_TYPE
     WHERE L.MBR_ID = #{MBR_ID}

       AND L.PNT_TYPE = #{PNT_TYPE}


       AND L.ORD_NO = #{ORD_NO}


       AND L.REG_DT >= TO_DATE(#{FROM_DT}, 'YYYYMMDD')


       AND L.REG_DT < TO_DATE(#{TO_DT}, 'YYYYMMDD') + 1

     ORDER BY L.LEDGER_NO DESC
  ) A WHERE ROWNUM <= 2000
)

SELECT MBR_ID, BAL_AMT, TO_CHAR(UPD_DT, 'YYYY-MM-DD HH24:MI:SS') AS UPD_DT
  FROM TB_PNT_BAL
 WHERE MBR_ID = #{mbrId}

SELECT 
  FROM TB_PNT_LEDGER L
 WHERE L.LEDGER_NO = #{ledgerNo}

SELECT 
  FROM TB_PNT_LEDGER L
 WHERE L.MBR_ID = #{MBR_ID}

   AND L.EXP_DT >= #{BASE_DT}
 ORDER BY L.EXP_DT, L.LEDGER_NO
   FOR UPDATE

